5	/**
6	 * Derives the single {@code identityKey} that every owner duplicate check is expressed through.
7	 *
8	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two
9	 * owners are duplicates only when their WHOLE keys are equal: because the normalized telephone is
10	 * part of the key, two members of the same household (same {@code householdId}) with different
11	 * telephones have different keys and are both allowed. The telephone is already normalized to E.164
12	 * and the email to lower case by {@link BuildOwner}; the {@code householdId} is assigned by
13	 * {@link AssignHousehold}. A missing email or household id contributes an empty segment.
14	 */
15	public final class OwnerIdentity {
16	
17	    private OwnerIdentity() {
18	    }
19	
20	    public static String key(Owner owner) {
21	        return segment(owner.getTelephone()) + '|' + segment(owner.getEmail()) + '|'
22	                + segment(owner.getHouseholdId());
23	    }
24	
25	    private static String segment(String value) {
26	        return value == null || value.isBlank() ? "" : value;
27	    }
28	}
