3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	import java.util.regex.Pattern;
6	
7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	/**
10	 * Shared handling for the owner {@code telephone}. Numbers are stored in E.164 form:
11	 * a leading {@code '+'} and country code are kept when present; otherwise country code
12	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
13	 * digits. Spaces, dashes and brackets are stripped, and the result must have 8 to 15
14	 * digits after the {@code '+'}.
15	 *
16	 * <p>Beyond that general range, the national number (the digits after the country code)
17	 * must have the exact length that country requires: {@code '+61'} takes 9 national
18	 * digits and {@code '+1'} takes 10. Other country codes are only bound by the general
19	 * 8-to-15 range.
20	 *
21	 * <p>So {@code '0412 345 678'} is stored as {@code '+61412345678'}.
22	 */
23	final class Telephones {
24	
25	    // Formatting characters allowed inside a supplied number: spaces, dashes and brackets.
26	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
27	
28	    // E.164: a '+' followed by 8 to 15 digits.
29	    private static final Pattern E164 = Pattern.compile("\\+\\d{8,15}");
30	
31	    // Country code -> required national-number length. Ordered longest-prefix-first so a
32	    // '+61' number is matched against '+61' before the shorter '+1'.
33	    private static final Map<String, Integer> NATIONAL_DIGITS = new LinkedHashMap<>();
34	
35	    static {
36	        NATIONAL_DIGITS.put("+61", 9);
37	        NATIONAL_DIGITS.put("+1", 10);
38	    }
39	
40	    private Telephones() {
41	    }
42	
43	    /**
44	     * Normalize a telephone to E.164 form.
45	     *
46	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
47	     */
48	    static String toE164(String telephone) throws InvalidTelephoneException {
49	        String stripped = SEPARATORS.matcher(telephone == null ? "" : telephone).replaceAll("");
50	        String e164;
51	        if (stripped.startsWith("+")) {
52	            // Keep the leading '+' and the country code exactly as supplied.
53	            e164 = stripped;
54	        }
55	        else {
56	            // No country code: assume '+61' and drop a single leading '0' from the national digits.
57	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
58	            e164 = "+61" + national;
59	        }
60	        if (!E164.matcher(e164).matches()) {
61	            throw new InvalidTelephoneException(
62	                    "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
63	        }
64	        // For a recognised country code, the national number must have exactly the length
65	        // that country requires (e.g. '+61' => 9 national digits, '+1' => 10).
66	        for (Map.Entry<String, Integer> country : NATIONAL_DIGITS.entrySet()) {
67	            String code = country.getKey();
68	            if (e164.startsWith(code)) {
69	                int nationalLength = e164.length() - code.length();
70	                if (nationalLength != country.getValue()) {
71	                    throw new InvalidTelephoneException("Telephone with country code '" + code
72	                            + "' must have " + country.getValue() + " national digits");
73	                }
74	                break;
75	            }
76	        }
77	        return e164;
78	    }
79	}
