1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
39	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
40	    @Mapping(target = "locality", expression = "java(locality(owner))")
41	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
43	    @Mapping(target = "identityKey",
44	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
45	    public abstract OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
49	     * present (non-null and non-blank), otherwise {@code PHONE}.
50	     */
51	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
52	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
53	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
54	    }
55	
56	    /**
57	     * Fixed city-to-region table: the owner's canonical region derived from its city.
58	     */
59	    static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
60	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
61	
62	    /**
63	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
64	     * VIC 3000-3099, QLD 4000-4099.
65	     */
66	    static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
67	            "NSW", new int[] {2000, 2099},
68	            "VIC", new int[] {3000, 3099},
69	            "QLD", new int[] {4000, 4099});
70	
71	    /**
72	     * Derives the owner's {@code locality} (canonical region string), preferring the
73	     * postcode: the region whose range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
74	     * contains the owner's postcode wins. When the postcode is absent or in no known
75	     * range, it falls back to the fixed city-to-region table
76	     * ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), or {@code "UNKNOWN"} when the
77	     * city is not in the table either.
78	     */
79	    protected String locality(Owner owner) {
80	        String region = regionFromPostcode(owner.getPostcode());
81	        if (region != null) {
82	            return region;
83	        }
84	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
85	    }
86	
87	    /**
88	     * The region whose inclusive postcode range contains the given 4-digit postcode, or
89	     * {@code null} when the postcode is absent, non-numeric, or in no known range.
90	     */
91	    private static String regionFromPostcode(String postcode) {
92	        if (postcode == null || postcode.isBlank()) {
93	            return null;
94	        }
95	        int value;
96	        try {
97	            value = Integer.parseInt(postcode.trim());
98	        }
99	        catch (NumberFormatException ex) {
100	            return null;
101	        }
102	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
103	            int[] range = entry.getValue();
104	            if (value >= range[0] && value <= range[1]) {
105	                return entry.getKey();
106	            }
107	        }
108	        return null;
109	    }
110	
111	    /**
112	     * The membership level is capped at this value; level 4 is reserved for tenure.
113	     */
114	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
115	
116	    /**
117	     * Returns the owner's membership level, a number from 1 to
118	     * {@value #MAX_MEMBERSHIP_LEVEL} assigned at creation: it starts at 1, gains 1 when
119	     * an email address is present, gains 1 when the owner has no namesakes
120	     * (namesakeCount is 0), and is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is
121	     * reserved for tenure).
122	     */
123	    public static int membershipLevel(Owner owner) {
124	        int level = 1;
125	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
126	        if (hasEmail) {
127	            level++;
128	        }
129	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
130	        if (noNamesakes) {
131	            level++;
132	        }
133	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
134	    }
135	
136	    /**
137	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
138	     * the registrationDate year (e.g. 'SMI-0007-M26'). Returns {@code null} when either the
139	     * customer code or the registration date is absent (e.g. legacy seed owners).
140	     */
141	    protected String membershipNumber(Owner owner) {
142	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
143	            return null;
144	        }
145	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
146	    }
147	
148	    /**
149	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
150	     * been created for this owner's {@code registrationDate}, using the same per-day
151	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
152	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
153	     */
154	    protected boolean bulkSignupWarning(Owner owner) {
155	        LocalDate registrationDate = owner.getRegistrationDate();
156	        if (registrationDate == null) {
157	            return false;
158	        }
159	        long count = ownerRepository.findAll().stream()
160	                .filter(existing -> !existing.getId().equals(owner.getId()))
161	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
162	                .count();
163	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
164	    }
165	
166	    /**
167	     * The Luhn check digit (0-9) computed over the digits contained in the owner's
168	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
169	     * legacy seed owners).
170	     */
171	    protected Integer checkDigit(Owner owner) {
172	        String customerCode = owner.getCustomerCode();
173	        if (customerCode == null) {
174	            return null;
175	        }
176	        int sum = 0;
177	        boolean dbl = true;
178	        for (int i = customerCode.length() - 1; i >= 0; i--) {
179	            char c = customerCode.charAt(i);
180	            if (c < '0' || c > '9') {
181	                continue;
182	            }
183	            int d = c - '0';
184	            if (dbl) {
185	                d *= 2;
186	                if (d > 9) {
187	                    d -= 9;
188	                }
189	            }
190	            sum += d;
191	            dbl = !dbl;
192	        }
193	        return (10 - (sum % 10)) % 10;
194	    }
195	
196	    public abstract Owner toOwner(OwnerDto ownerDto);
197	
198	    @Mapping(target = "id", ignore = true)
199	    @Mapping(target = "pets", ignore = true)
200	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
201	
202	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
203	
204	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
205	
206	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
207	        OwnerPageDto ownerPageDto = new OwnerPageDto();
208	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
209	        ownerPageDto.setPage(ownerPage.getNumber());
210	        ownerPageDto.setSize(ownerPage.getSize());
211	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
212	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
213	        return ownerPageDto;
214	    }
215	}
