1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.List;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	
12	/**
13	 * When the request opted into a shared household ({@code sharesHousehold} true), assigns the new
14	 * owner a stable {@code householdId} shared by everyone at the same last name and address (the last
15	 * name compared case-insensitively with runs of whitespace collapsed, and the address in its
16	 * normalized form).
17	 *
18	 * <p>The identifier is derived deterministically from the normalized last name and address, so every
19	 * owner in the household resolves to the same value even across separate requests. If an existing
20	 * household member already carries an id, that value is reused for stability; any members still
21	 * missing it are back-filled, so both ends of the shared household carry the same id.
22	 */
23	public class AssignHousehold {
24	
25	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
26	        if (!Boolean.TRUE.equals(sharesHousehold)) {
27	            return;
28	        }
29	        String lastName = normalize(owner.getLastName());
30	        String address = Addresses.normalize(owner.getAddress());
31	        List<Owner> members = ownerRepository.findAll().stream()
32	                .filter(existing -> !existing.getId().equals(owner.getId()))
33	                .filter(existing -> normalize(existing.getLastName()).equals(lastName)
34	                        && Addresses.normalize(existing.getAddress()).equals(address))
35	                .toList();
36	        // Reuse an id already held by a household member for stability; otherwise derive one.
37	        String householdId = members.stream()
38	                .map(Owner::getHouseholdId)
39	                .filter(id -> id != null && !id.isBlank())
40	                .findFirst()
41	                .orElseGet(() -> deriveHouseholdId(lastName, address));
42	        owner.setHouseholdId(householdId);
43	        for (Owner member : members) {
44	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
45	                member.setHouseholdId(householdId);
46	                ownerRepository.save(member);
47	            }
48	        }
49	    }
50	
51	    private static String deriveHouseholdId(String lastName, String address) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder("HH-");
56	            for (int i = 0; i < 6; i++) {
57	                sb.append(String.format("%02X", digest[i]));
58	            }
59	            return sb.toString();
60	        }
61	        catch (NoSuchAlgorithmException e) {
62	            throw new IllegalStateException("SHA-256 not available", e);
63	        }
64	    }
65	
66	    private static String normalize(String value) {
