5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Rejects creating an owner whose whole {@code identityKey} already belongs to another owner.
10	 * This is the single, consolidated duplicate check: the former separate telephone, email and
11	 * household checks are all expressed through {@link OwnerIdentity#key(Owner)}. Runs after
12	 * {@link AssignHousehold} so the new owner's {@code householdId} is part of the compared key.
13	 */
14	public class EnsureUniqueIdentity {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
17	            throws DuplicateIdentityException {
18	        String identityKey = OwnerIdentity.key(owner);
19	        boolean inUse = ownerRepository.findAll().stream()
20	                .filter(existing -> !existing.getId().equals(owner.getId()))
21	                .anyMatch(existing -> OwnerIdentity.key(existing).equals(identityKey));
22	        if (inUse) {
23	            throw new DuplicateIdentityException(
24	                    "An owner with identityKey " + identityKey + " already exists");
25	        }
26	    }
27	}
